  "Детали мероприятия, оборудование, тайминг…": { kg: "Иш-чаранын деталдары, жабдуулар, убакыт планы…", en: "Event details, equipment, timing…", kz: "Іс-шара мәліметтері, жабдықтар, тайминг…" },
  "Отправить заявку на мероприятие": { kg: "Иш-чарага өтүнмө жөнөтүү", en: "Send event request", kz: "Іс-шара өтінімін жіберу" },
  "Условия и доступность залов подтверждает администратор после проверки.": { kg: "Залдардын шарттарын жана жеткиликтүүлүгүн текшергенден кийин администратор ырастайт.", en: "Hall terms and availability are confirmed by the administrator after verification.", kz: "Зал шарттары мен қолжетімділігін тексергеннен кейін әкімші растайды." },
  "Спасибо! Ваш вопрос принят. Администратор свяжется с вами.": { kg: "Рахмат! Сурооңуз кабыл алынды. Администратор сиз менен байланышат.", en: "Thank you! Your question has been received. The administrator will contact you.", kz: "Рақмет! Сұрағыңыз қабылданды. Әкімші сізбен байланысады." },
  "Задать вопрос": { kg: "Суроо берүү", en: "Ask a question", kz: "Сұрақ қою" },
  "Оставьте контакты и вопрос — администратор свяжется с вами.": { kg: "Байланыш маалыматыңызды жана сурооңузду калтырыңыз — администратор сиз менен байланышат.", en: "Leave your contact details and question — the administrator will contact you.", kz: "Байланыс деректеріңіз бен сұрағыңызды қалдырыңыз — әкімші сізбен байланысады." },
  "Тема": { kg: "Тема", en: "Subject", kz: "Тақырып" },
  "О чём вопрос?": { kg: "Суроо эмнеге байланыштуу?", en: "What is your question about?", kz: "Сұрағыңыз не туралы?" },
  "Сообщение": { kg: "Билдирүү", en: "Message", kz: "Хабарлама" },
  "Ваш вопрос…": { kg: "Сурооңуз…", en: "Your question…", kz: "Сұрағыңыз…" },
  "Отправить вопрос": { kg: "Суроону жөнөтүү", en: "Send question", kz: "Сұрақты жіберу" },
  "Заявка принята. Администратор уточнит условия посещения и свободное время.": { kg: "Өтүнмө кабыл алынды. Администратор баруу шарттарын жана бош убакытты тактайт.", en: "Your request has been received. The administrator will confirm visit conditions and available times.", kz: "Өтінім қабылданды. Әкімші келу шарттары мен бос уақытты нақтылайды." },
  "Заявка на посещение": { kg: "Барууга өтүнмө", en: "Visit request", kz: "Келуге өтінім" },
  "Оставьте контакты — администратор подскажет свободное время и условия.": { kg: "Байланыш маалыматыңызды калтырыңыз — администратор бош убакытты жана шарттарды айтып берет.", en: "Leave your contact details — the administrator will advise on available times and conditions.", kz: "Байланыс деректеріңізді қалдырыңыз — әкімші бос уақыт пен шарттарды хабарлайды." },
