const BLOCKED_BUSINESS_TRANSLATIONS = new Set<string>([
  // Refund/legal policy is OWNER / LEGAL DECISION REQUIRED in current V7.
  "При отмене за 14 и более дней возвращается 100% предоплаты за минусом комиссии перевода. При отмене за 7–14 дней возвращается 50%. При отмене менее чем за 7 дней удерживается стоимость одних суток забронированных номеров.",

  // Do not turn historical FAQ wording into a new confirmed business promise.
  "Собственного трансфера нет, но администратор может помочь найти такси.",

  // Wellness inclusion must follow current confirmed business policy only.
  "В проживание входит трёхразовое питание, а также утренний доступ с 09:00 до 12:00 к тренажёрному залу, крытому бассейну и горячим источникам.",
]);

export function t(text: string, locale: Locale): string {
  if (locale === "ru") return text;

  // Current Russian V7 content remains the factual authority.
  // Historical dictionary must never silently override disputed business facts.
  if (BLOCKED_BUSINESS_TRANSLATIONS.has(text)) return text;

  return DICT[text]?.[locale] ?? text;
}
